{
  "pass": false,
  "problems": [
    {
      "type": "中身のずれ",
      "where": "summaryの hs",
      "detail": "stdにある「国会での委員の割当てや質問時間の決定」「政党の要件」についての情報が一切なく、会派と政党の定義の説明に置き換わっており、中身が大きくずれています。",
      "fix": "stdの内容に合わせて、国会での割当てや質問時間、政党の要件に関する説明に書き直してください。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/0/text の hs",
      "detail": "stdは「政党交付金を受けられる政党かどうかは何で決まるか」という問いですが、hsでは「会派と政党は同じものか」という別の問いになっており、中身がずれています。",
      "fix": "stdの問いに合わせて、政党交付金を受けられる条件についての問いに直してください。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/text の hs",
      "detail": "stdにある「会派の認定は各議院の議院運営委員会の議決で決まる（立法事務費法第5条）」という重要な事実が抜けています。",
      "fix": "会派の認定方法や根拠法律についてもhsに含めてください。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/2/text の hs",
      "detail": "stdにある「直近の衆議院総選挙・直近2回の参議院通常選挙のいずれかで」という条件が、「最近の国政選挙」と曖昧にまとめられており、詳細な条件が抜けています。",
      "fix": "衆議院と参議院の選挙に関する条件を正しく反映させてください。"
    }
  ]
}
